// FilmCalc i18n system. Plain global script (no bundler) — same pattern as
// the rest of js/: attaches globals onto window, loaded via <script src>
// before dev-cost-calc.js / dev-cost-ui.js / film-lookup.js / modals.js.
//
// Only English ships today, but every user-facing string in the app is
// already routed through t()/applyI18n() so adding a second locale later is
// just adding another STRINGS.<locale> object and a switcher — no further
// string-hunting required.

